  "slug": "daly-city-california",
  "city": "Daly City",
  "state": "California",
  "tagline": "Stationery. Collections. Daly City.",
  "intro": "Daly City sits just south of San Francisco, a city of hills, fog, and families from around the world. The Cow Palace, an arena that hosted the Beatles in 1964 and decades of rodeos and shows, anchors the city&#x27;s north side, and Serramonte Center draws shoppers from across the Peninsula. Thornton State Beach offers a wild stretch of Pacific shore below the bluffs, and Westlake, a planned community built after World War II, gave the city its curving streets and midcentury homes. San Bruno Mountain rises to the east with trails and sweeping bay views.",
