  "intro": "Paterson rises around the Great Falls of the Passaic River, where water drops over basalt cliffs in the middle of the city and a national historical park now protects the site. Alexander Hamilton helped found Paterson as the nation&#x27;s first planned industrial city, and mills powered by the falls later made it a center of the silk industry, earning the name Silk City. The Paterson Museum tells that working history, and Hinchliffe Stadium, one of the few remaining Negro Leagues ballparks, stands as a landmark of sports and community memory. The city also claims comedian Lou Costello among its native sons.",
