  "tagline": "Collections. Home. Springfield.",
  "intro": "Springfield sits on the Connecticut River in western Massachusetts, a city nicknamed the City of Firsts for its long list of innovations. Basketball was invented here in 1891 by James Naismith, and the Naismith Memorial Basketball Hall of Fame now honors the game beside the river. The Springfield Armory National Historic Site preserves the nation&#x27;s first armory, and the city also claims Theodor Geisel, better known as Dr. Seuss, among its native sons. Downtown and the riverfront keep museums, theaters, and parks within walking distance, and the river itself has shaped trade and travel for centuries.",
